import React, { useState, useEffect, useRef } from 'react';
// Import from a CDN (esm.sh) to resolve the module errors from before
import { Link as ScrollLink } from 'https://esm.sh/react-scroll';
import {
    Box, Menu, Linkedin, Twitter, Github, Mail, Phone, Facebook, Instagram, Home, Info, Users, Folder, Activity, TrendingUp, Settings, MapPin
} from 'https://esm.sh/react-feather';

//==============================================================================
// 1. INLINED STYLES
// All the CSS from your <style> tag is placed here inside a React component.
//==============================================================================
const AppStyles = () => (
  <style>{`
    /* Set the default font for the entire page */
    body {
        font-family: 'Inter', sans-serif;
        background-color: #f8fafc; /* A slightly cooler light gray (slate-50) */
        /* Antialiasing for smoother fonts */
        -webkit-font-smoothing: antialiased;
        -moz-osx-font-smoothing: grayscale;
    }

    /* Custom scrollbar for a polished look */
    ::-webkit-scrollbar { width: 10px; }
    ::-webkit-scrollbar-track { background: #e2e8f0; /* slate-200 */ }
    ::-webkit-scrollbar-thumb {
        background-color: #3b82f6; /* blue-500 */
        border-radius: 20px;
        border: 3px solid #e2e8f0; /* slate-200 */
    }
    ::-webkit-scrollbar-thumb:hover { background-color: #2563eb; /* blue-600 */ }

    /* A subtle gradient for the hero section background */
    .hero-gradient {
        background: linear-gradient(135deg, rgba(255, 255, 255, 1) 0%, rgba(240, 245, 255, 1) 100%);
    }

    /* Animation for cards and sections on scroll */
    .reveal-on-scroll {
        opacity: 0;
        transform: translateY(30px);
        transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .reveal-on-scroll.is-visible {
        opacity: 1;
        transform: translateY(0);
    }

    /* Hero Image Carousel Styles */
    #hero-image-react {
        /* This transition matches the JS logic */
        transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out;
    }
    /* This class is added by React to trigger the fade */
    #hero-image-react.is-fading {
        opacity: 0.4;
        transform: scale(1.03);
    }

    .indicator { transition: all 0.3s ease-in-out; }
    .indicator:hover {
        transform: scale(1.3);
        opacity: 0.8;
    }
    .indicator.active { 
        animation: pulse 1s infinite alternate; 
        transform: scale(1.1);
    }

    @keyframes pulse {
        from { opacity: 1; transform: scale(1.1); }
        to { opacity: 0.7; transform: scale(1); }
    }
  `}</style>
);

//==============================================================================
// 2. DATA FOR THE PAGE
// Manually extracted from your repetitive HTML to make the code cleaner
//==============================================================================
const facultyData = [
    { name: 'Dr. Ajay Kumar', role: 'Principal Investigator', img: '/faculties/ajay.jpeg', link: 'https://www.adishankara.ac.in/department/faculty/25', description: 'Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.', socials: { linkedin: '#', twitter: '#' } },
    { name: 'Mr. Albins Paul', role: 'Co-Investigator', img: '/faculties/albins.jpg', link: 'https://www.adishankara.ac.in/department/faculty/66', description: "Assistant Professor at ASIET's ECE Department, specializing in Microwave & Television Engineering.", socials: { linkedin: '#', github: '#' } },
    { name: 'Prof. P.V. Rajaraman', role: 'Co-Investigator', img: '/faculties/rajaraman.jpg', link: 'https://www.adishankara.ac.in/department/faculty/375', description: 'Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.', socials: { linkedin: '#', twitter: '#' } },
    { name: 'Mr. Abhijith Pm', role: 'Project Associate', img: '/faculties/abhijith.jpeg', link: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', description: null, socials: { linkedin: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', twitter: '#' } },
    { name: 'Mrs. Hasna Hameed', role: 'Project Associate', img: '/faculties/hasna2.JPG', link: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', description: null, socials: { linkedin: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', twitter: '#' } },
    { name: 'Ms. Arathy Surendran', role: 'Project Associate', img: '/faculties/arathy.JPG', link: 'https://www.linkedin.com/in/arathy-surendran/', description: null, socials: { linkedin: 'https://www.linkedin.com/in/arathy-surendran/', twitter: '#' } },
    { name: 'Mr. Bhagyaraj J', role: 'Project Assistant', img: '/faculties/bhagyaraj.jpeg', link: '#', description: null, socials: { linkedin: '#', github: '#' } },
    { name: 'Mr. Amaljith N Raj', role: 'Project Assistant', img: '/faculties/amaljith.JPG', link: '#', description: null, socials: { linkedin: '#', github: '#' } },
    { name: 'Mrs. Jebina EA', role: 'Project Assistant', img: '/faculties/jibinaea.jpeg', link: '#', description: null, socials: { linkedin: '#', github: '#' } },
];

const projectData = [
    { title: 'Intelligent Sensor Module', img: '/sensor_modules/module3.jpg', description: 'Developing a smart sensor module for real-time monitoring and management of environmental pollutants.' },
    { title: 'Smart Water Level Monitoring', img: '/sensor_modules/water.png', description: 'A robust solution for monitoring water levels with an integrated alert system to mitigate flood risks.' },
    { title: 'Digital Water Distribution', img: '/sensor_modules/water_authorityy.jpeg', description: 'Creating a digital twin to efficiently monitor and manage water distribution networks in urban areas.' },
    { title: 'Startup & Skill Development', img: '/sensor_modules/skill.jpg', description: 'Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.' },
    { title: 'Explainable AI Software', img: '/sensor_modules/ai.jpeg', description: 'Building analysis software based on Explainable AI (XAI) to bring transparency and trust to complex IoT systems.' },
];


//==============================================================================
// 3. THE COMPLETE SINGLE PAGE COMPONENT
// This function IS the entire page.
//==============================================================================
export default function AiIotInnovationCenter() {

    // --- STATE ---
    // For mobile menu
    const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
    
    // For Hero Carousel
    const [carouselImages, setCarouselImages] = useState([]);
    const [currentIndex, setCurrentIndex] = useState(0);
    const [isFading, setIsFading] = useState(false); // Used to trigger the fade animation
    const intervalRef = useRef(null); // Holds the ID of the auto-slide interval
    const currentIndexRef = useRef(currentIndex); // Holds the current index for the interval to prevent stale state
    
    // --- REFS ---
    // This will hold an array of all elements that need to animate on scroll
    const scrollRefs = useRef([]);
    // A helper function to add elements to the ref array
    const addToScrollRefs = (el) => {
        if (el && !scrollRefs.current.includes(el)) {
            scrollRefs.current.push(el);
        }
    };

    // --- EFFECTS (LOGIC) ---

    // Effect for REVEAL ON SCROLL logic
    useEffect(() => {
        // This is the JS logic from your <script> tag, converted to React
        const observer = new IntersectionObserver(
            (entries) => {
                entries.forEach(entry => {
                    if (entry.isIntersecting) {
                        entry.target.classList.add('is-visible');
                        observer.unobserve(entry.target);
                    }
                });
            },
            { threshold: 0.1 } // An element is "in view" when 10% visible
        );

        // We observe every element that was added to the scrollRefs array
        const currentRefs = [...scrollRefs.current];
        currentRefs.forEach(ref => {
            if (ref) {
                observer.observe(ref);
            }
        });

        // Cleanup function: disconnect the observer when the component unmounts
        return () => {
            currentRefs.forEach(ref => {
                if (ref) {
                    observer.unobserve(ref);
                }
            });
        };
    }, [scrollRefs.current.length]); // Re-run if new elements are added (e.g., page resize)

    
    // Effect for HERO CAROUSEL logic
    
    // 1. Keep the currentIndexRef in sync with the state
    useEffect(() => {
        currentIndexRef.current = currentIndex;
    }, [currentIndex]);

    // 2. Fetch images on component mount
    useEffect(() => {
        fetch('/carousel-images/carousel-images.json')
            .then(res => {
                if (!res.ok) throw new Error(`HTTP error! status: ${res.status}`);
                return res.json();
            })
            .then(data => setCarouselImages(data))
            .catch(err => {
                console.error("Could not load carousel images:", err);
                // Set fallback image if fetch fails
                setCarouselImages([{ 
                    src: 'https://placehold.co/1200x600/f0f9ff/334155?text=Image+Not+Available', 
                    alt: 'Image not available' 
                }]);
            });
    }, []); // Empty array `[]` means this runs only once on mount

    // 3. Helper function to change the slide with a fade effect
    const changeSlide = (newIndex) => {
        // Prevent re-fading if clicking the same slide
        if (newIndex === currentIndexRef.current) return;
        
        setIsFading(true); // Trigger the fade-out CSS class
        
        // Wait for the fade-out animation to finish, then change image and fade in
        setTimeout(() => {
            setCurrentIndex(newIndex);
            setIsFading(false); // Remove the fade-out class, triggering fade-in
        }, 500); // This duration must match the CSS transition duration
    };

    // 4. Start/Stop the auto-slide interval
    useEffect(() => {
        // Only start if there's more than one image
        if (carouselImages.length > 1) {
            intervalRef.current = setInterval(() => {
                // Use the ref here to get the *latest* index
                const newIndex = (currentIndexRef.current + 1) % carouselImages.length;
                changeSlide(newIndex);
            }, 4000); // Change image every 4 seconds
        }
        // Cleanup interval on unmount
        return () => clearInterval(intervalRef.current);
    }, [carouselImages.length]); // Re-run this effect if the number of images changes

    // Get the current image details, with a fallback for initial render
    const currentImage = carouselImages[currentIndex] || { 
        src: 'https://placehold.co/1200x600/f0f9ff/334155?text=Loading...', 
        alt: 'Loading image' 
    };

    // --- RENDER (The JSX/HTML) ---
    // All HTML from your file is converted to JSX here
    return (
        // React.Fragment shorthand <>...</>
        <>
            {/* 1. Add the inlined styles to the page */}
            <AppStyles />
            
            {/* ===== HEADER ===== */}
            {/* All `class` attributes are changed to `className` */}
            <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
                <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                    <nav className="flex justify-between items-center h-16">
                        {/* Logo */}
                        <a href="#" className="flex items-center gap-2 text-xl md:text-2xl font-bold text-blue-600">
                            {/* The <svg> is replaced with the React component */}
                            <Box size={28} />
                            <span className="hidden sm:inline">Center for AI-IoT Innovation</span>
                            <span className="sm:hidden">AI-IoT Center</span>
                        </a>
                        {/* Desktop Navigation Links */}
                        <div className="hidden md:flex items-center space-x-4">
                            <ul className="flex items-center space-x-8">
                                {/* `href` links are replaced with <ScrollLink> */}
                                <li><ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">About</ScrollLink></li>
                                <li><ScrollLink to="faculty" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">Faculty</ScrollLink></li>
                                <li><ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">Projects</ScrollLink></li>
                                <li><ScrollLink to="contact" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300">Contact</ScrollLink></li>
                            </ul>
                            {/* CTA Buttons */}
                            <div className="flex items-center space-x-2">
                               {/* `target="_blank"` links need `rel="noopener noreferrer"` */}
                               <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AirAware</a>
                               <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AWS</a>
                            </div>
                        </div>
                        {/* Mobile Menu Button */}
                        <button 
                            className="md:hidden text-slate-600 hover:text-blue-600" 
                            aria-label="Open menu"
                            // `onClick` toggles the mobile menu state
                            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
                        >
                            <Menu />
                        </button>
                    </nav>
                </div>
                {/* Mobile Menu Dropdown: Rendered only if `isMobileMenuOpen` is true */}
                {isMobileMenuOpen && (
                    <div className="md:hidden bg-white/95 backdrop-blur-lg border-t border-slate-200">
                        <ul className="flex flex-col items-center space-y-4 p-4">
                            {/* Links here close the menu when clicked */}
                            <li><ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300" onClick={() => setIsMobileMenuOpen(false)}>About</ScrollLink></li>
                            <li><ScrollLink to="faculty" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300" onClick={() => setIsMobileMenuOpen(false)}>Faculty</ScrollLink></li>
                            <li><ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300" onClick={() => setIsMobileMenuOpen(false)}>Projects</ScrollLink></li>
                            <li><ScrollLink to="contact" smooth={true} offset={-70} duration={500} className="cursor-pointer text-slate-600 hover:text-blue-600 font-medium transition duration-300" onClick={() => setIsMobileMenuOpen(false)}>Contact</ScrollLink></li>
                        </ul>
                        <div className="flex justify-center items-center space-x-2 p-4 border-t border-slate-200">
                           <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md">AirAware</a>
                           <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md">AWS</a>
                        </div>
                    </div>
                )}
            </header>

            {/* ===== MAIN CONTENT ===== */}
            <main className="flex-grow">
                {/* --- Hero Section --- */}
                {/* `id` attributes are kept for the ScrollLinks to target */}
                <section id="hero" className="relative hero-gradient py-20 md:py-32">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                        {/* `ref={addToScrollRefs}` is added to all elements with "reveal-on-scroll" */}
                        <h1 ref={addToScrollRefs} className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight reveal-on-scroll">
                            <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                            <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                        </h1>
                        {/* `style` attribute is converted to a JS object */}
                        <p ref={addToScrollRefs} className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto reveal-on-scroll" style={{ transitionDelay: '150ms' }}>
                            The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                        </p>
                        <div ref={addToScrollRefs} className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12 reveal-on-scroll" style={{ transitionDelay: '300ms' }}>
                            <ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105">Explore Projects</ScrollLink>
                            <ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105">Learn More</ScrollLink>
                        </div>
                        {/* Container for the image carousel */}
                        <div ref={addToScrollRefs} className="relative max-w-5xl mx-auto reveal-on-scroll" style={{ transitionDelay: '450ms' }}>
                            <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
                            <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                                {/* This `img` is now controlled by React state */}
                                <img 
                                    id="hero-image-react" // New ID for CSS targeting
                                    src={currentImage.src} 
                                    alt={currentImage.alt} 
                                    // The `is-fading` class is applied conditionally
                                    className={`w-full h-auto object-cover ${isFading ? 'is-fading' : ''}`}
                                />
                            </div>
                            {/* Indicators are now rendered dynamically from state */}
                            {carouselImages.length > 1 && (
                                <div className="flex justify-center mt-6 space-x-3">
                                    {carouselImages.map((_, index) => (
                                        <div 
                                            key={index} 
                                            onClick={() => changeSlide(index)} 
                                            // The `active` class is applied conditionally
                                            className={`indicator w-3 h-3 rounded-full cursor-pointer ${currentIndex === index ? 'bg-blue-600 active' : 'bg-blue-300'}`}
                                        ></div>
                                    ))}
                                </div>
                            )}
                        </div>
                    </div>
                </section>

                {/* --- About Section --- */}
                <section id="about" className="py-20 bg-white">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div ref={addToScrollRefs} className="text-center mb-12 reveal-on-scroll">
                            <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
                            <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">Pioneering research where intelligence meets connectivity.</p>
                        </div>
                        <div className="grid md:grid-cols-2 gap-12 items-center">
                            <div ref={addToScrollRefs} className="reveal-on-scroll">
                                <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                                    <img src="/carousel-images/1 (4).jpg" alt="Collaborative team working in a modern tech lab" loading="lazy" width="800" height="600" className="w-full h-auto object-cover" />
                                </div>
                            </div>
                            <div ref={addToScrollRefs} className="text-lg text-slate-600 space-y-6 reveal-on-scroll" style={{ transitionDelay: '150ms' }}>
                                <p>The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI). The lab is equipped with hardware development tools, computing systems, and educational resources to support research and development in this area. The center provides resources for both theoretical research and practical applications, aiming to advance the integration of AI technologies with IoT systems.</p>
                                <p>We provide a state-of-the-art environment equipped with powerful computing resources and hardware development tools. This fosters a culture of innovation, empowering researchers and students to build the next generation of smart solutions.</p>
                            </div>
                        </div>
                    </div>
                </section>

                {/* --- Faculty Section --- */}
                <section id="faculty" className="py-20 bg-slate-50">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div ref={addToScrollRefs} className="text-center mb-12 reveal-on-scroll">
                            <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Meet Our Expert Faculty</h2>
                            <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">The brilliant minds leading our research and innovation.</p>
                        </div>
                        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                            
                            {/* The hardcoded cards are replaced with a .map() of the data */}
                            {facultyData.map((person, index) => (
                                <div 
                                    key={person.name} // React needs a unique key for list items
                                    ref={addToScrollRefs} // Add this card to the scroll animation list
                                    className="text-center bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll" 
                                    style={{ transitionDelay: `${index * 150}ms` }} // Stagger the animation
                                >
                                    <a href={person.link} target="_blank" rel="noopener noreferrer" className="block">
                                        <img className="w-32 h-32 mx-auto rounded-full mb-4 object-cover shadow-lg" src={person.img} alt={`Photo of ${person.name}`} loading="lazy" width="128" height="128" 
                                            // `onerror` is converted to `onError`
                                            onError={(e) => { e.target.onerror = null; e.target.src='https://placehold.co/128x128/e0e0e0/000000?text=Faculty'; }} 
                                        />
                                    </a>
                                    <a href={person.link} target="_blank" rel="noopener noreferrer" className="hover:text-blue-800 transition duration-300"><h4 className="text-xl font-bold text-blue-700">{person.name}</h4></a>
                                    <p className="text-slate-500 font-medium mb-2">{person.role}</p>
                                    <p className="text-slate-600 text-sm mb-4 h-10"> {/* h-10 ensures alignment even if description is missing */}
                                        {person.description}
                                    </p>
                                    <div className="flex justify-center space-x-4">
                                        {/* Conditionally render icons only if they exist in the data */}
                                        {person.socials?.linkedin && <a href={person.socials.linkedin} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500"><Linkedin /></a>}
                                        {person.socials?.twitter && <a href={person.socials.twitter} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500"><Twitter /></a>}
                                        {person.socials?.github && <a href={person.socials.github} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500"><Github /></a>}
                                    </div>
                                </div>
                            ))}
                        </div>
                    </div>
                </section>

                {/* --- Projects Section --- */}
                <section id="projects" className="py-20 bg-white">
                    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                        <div ref={addToScrollRefs} className="text-center mb-12 reveal-on-scroll">
                            <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Our Ongoing Projects</h2>
                            <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">From concept to reality, we're building solutions that matter.</p>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                            {/* Project cards are also generated from data */}
                            {projectData.map((project, index) => (
                                <div 
                                    key={project.title}
                                    ref={addToScrollRefs}
                                    className="bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll" 
                                    style={{ transitionDelay: `${index * 100}ms` }}
                                >
                                    <img 
                                        src={project.img}
                                        alt={project.title}
                                        className="w-full h-40 object-cover rounded-lg mb-4" 
                                        loading="lazy" 
                                        width="400" height="200"
                                    />
                                    <h4 className="text-xl font-bold text-blue-700 mb-2">{project.title}</h4>
                                    <p className="text-slate-600 text-sm">
                                        {project.description}
                                    </p>
                                </div>
                            ))}
                        </div>
                    </div>
                </section>
                
                {/* --- Contact Section --- */}
                <section id="contact" className="py-20 bg-slate-50">
                    <div ref={addToScrollRefs} className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center reveal-on-scroll">
                        <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800 mb-4">Let's Build the Future Together</h2>
                        <p className="text-lg text-slate-600 mb-8">Have a project in mind, a question, or want to collaborate? We'd love to hear from you.</p>
                        <div className="flex flex-col sm:flex-row justify-center items-center gap-6">
                            <a href="mailto:aiiot@adishankara.ac.in" target="_blank" rel="noopener noreferrer" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105"><Mail className="w-5 h-5" /> Email Us</a>
                            <a href="tel:+919846900310" target="_blank" rel="noopener noreferrer" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-slate-100 hover:bg-slate-200 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105"><Phone className="w-5 h-5" /> Call +919846900310</a>
                        </div>
                    </div>
                </section>
            </main>

            {/* ===== FOOTER ===== */}
            <footer className="bg-slate-800 text-slate-400">
                <div className="max-w-7xl mx-auto py-12 px-4 sm:px-6 lg:px-8">
                    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                        {/* About */}
                        <div className="space-y-4">
                            <div className="flex items-center gap-2 text-xl font-bold text-white mb-4">
                                <Box />
                                <span>AI-IoT</span>
                            </div>
                            <div className="flex space-x-4 pt-2">
                                <a href="#" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-400" aria-label="Facebook"><Facebook className="w-5 h-5" /></a>
                                <a href="#" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-400" aria-label="Twitter"><Twitter className="w-5 h-5" /></a>
                                <a href="#" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-400" aria-label="LinkedIn"><Linkedin className="w-5 h-5" /></a>
                                <a href="#" target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-400" aria-label="Instagram"><Instagram className="w-5 h-5" /></a>
                            </div>
                        </div>
                        {/* Quick Links */}
                        <div className="space-y-4">
                            <h4 className="text-lg font-semibold text-white">Quick Links</h4>
                            <ul className="space-y-2">
                                <li><ScrollLink to="hero" smooth={true} duration={500} className="cursor-pointer text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Home className="w-4 h-4" /> Home</ScrollLink></li>
                                <li><ScrollLink to="about" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Info className="w-4 h-4" /> About Us</ScrollLink></li>
                                <li><ScrollLink to="faculty" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Users className="w-4 h-4" /> Faculty</ScrollLink></li>
                                <li><ScrollLink to="projects" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Folder className="w-4 h-4" /> Projects</ScrollLink></li>
                                <li><ScrollLink to="contact" smooth={true} offset={-70} duration={500} className="cursor-pointer text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Phone className="w-4 h-4" /> Contact</ScrollLink></li>
                            </ul>
                        </div>
                        {/* Services */}
                        <div className="space-y-4">
                            <h4 className="text-lg font-semibold text-white">Services</h4>
                            <ul className="space-y-2">
                                <li><a href="#" target="_blank" rel="noopener noreferrer" className="text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Activity className="w-4 h-4" /> IoT Monitoring</a></li>
                                <li><a href="#" target="_blank" rel="noopener noreferrer" className="text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><TrendingUp className="w-4 h-4" /> Predictive Models</a></li>
                                <li><a href="#" target="_blank" rel="noopener noreferrer" className="text-sm hover:text-blue-400 transition duration-300 flex items-center gap-2"><Settings className="w-4 h-4" /> System Integration</a></li>
                            </ul>
                        </div>
                        {/* Contact Info */}
                        <div className="space-y-4">
                            <h4 className="text-lg font-semibold text-white">Contact Information</h4>
                            <div className="space-y-2 text-sm">
                                <p className="flex items-start gap-2"><MapPin className="w-4 h-4 mt-0.5 flex-shrink-0" /><span>Adi Shankara Institute of Engineering and Technology<br />Kalady 683574, Ernakulam<br />Kerala, India</span></p>
                                <p className="flex items-center gap-2"><Mail className="w-4 h-4" /><a href="mailto:aiiot@adishankara.ac.in" target="_blank" rel="noopener noreferrer" className="hover:text-blue-400">aiiot@adishankara.ac.in</a></p>
                                <p className="flex items-center gap-2"><Phone className="w-4 h-4" /><a href="tel:04842463825" target="_blank" rel="noopener noreferrer" className="hover:text-blue-400">0484 246 3825</a></p>
                            </div>
                        </div>
                    </div>
                    <div className="border-t border-slate-700 mt-8 pt-8 text-center">
                        <p className="text-sm">&copy; 2025 Center for AI-IoT Innovation. All Rights Reserved.</p>
                        <p className="mt-2 text-xs text-slate-500">Designed for a smarter, more connected future.</p>
                    </div>
                </div>
            </footer>
        </>
    );
};
